changeSet.sql:
CREATE OR ALTER procedure [graph].[AssetBrowser_ImpactHop] @ancestry int, -- 1 = all, 2 = direct-parent, 3 = type-only @hierarchyKey varchar(50), @assets dbo.AssetBrowserImpactTable readonly, @preloadedIntersects dbo.Ids readonly, @predicateUid uniqueidentifier, @direction char(1) = 'F', -- (F)orward, (B)ackward @resourceId int, @isAdmin bit, @includeNonLeaf bit = 1, @includeDescendantAssets bit = 1 as begin set nocount on;
declare @offLimitImpactFunctionalTypes table (ID int) declare @maxLineageDescendants int = 500
insert into @offLimitImpactFunctionalTypes (ID) values (15) if @ancestry = 1 begin insert into @offLimitImpactFunctionalTypes (ID) values (1),(3),(4) end
drop table if exists #ids; create table #ids ([Key] varchar(50), ID bigint);
drop table if exists #hops; create table #hops (IntersectID bigint, IntersectUid uniqueidentifier, SubjectID bigint, SubjectSalt varchar(25), [from] varchar(50), ObjectId bigint, ObjectSalt varchar(25), [to] varchar(50), PredicateID int); create nonclustered index IX_TempHops_IntersectID on #hops (IntersectID asc);
insert into #ids ([Key], ID) select O.[Key], A.ID from @assets O inner join Asset A on A.Uid = O.Uid;
--Predicates of type 16 means that we want to see contents of process diagram, so lets unpack it and add diagram assets manually if exists(select top 1 * from [Predicate] where uid = @predicateUid and [type] = 16) begin
drop table if exists #diagramIds; create table #diagramIds ([Key] varchar(50), ID bigint);
insert into #diagramIds select ass.[key], a.id from @assets ass inner join asset a on a.uid = ass.uid where a.object != 'Diagram'
;with asset_cte as( select da.id, h.[key] from #diagramIds h inner join assetprocessdiagram d on d.assetid = h.id inner join asset a on a.id = h.id inner join processexpandeddata pxd on pxd.diagramassetuid = a.uid inner join asset da on da.uid = pxd.fromuid inner join assettype at on at.id = da.assettypeid inner join intersecttype it on at.uid = it.subjectuid inner join [predicate] p on it.predicateid = p.id where h.id is not null and p.type = 16 union select da.id, h.[key] from #diagramIds h inner join assetprocessdiagram d on d.assetid = h.id inner join asset a on a.id = h.id inner join processexpandeddata pxd on pxd.diagramassetuid = a.uid inner join asset da on da.uid = pxd.touid inner join assettype at on at.id = da.assettypeid inner join intersecttype it on at.uid = it.subjectuid inner join [predicate] p on it.predicateid = p.id where h.id is not null and p.type = 16 ) insert into #ids select [key],id from asset_cte end
declare @salt varchar(25) = graph.Hop_GenerateSalt()
-- Relationships if @direction = 'B' begin insert into #hops (IntersectID, IntersectUid, SubjectID, [from], ObjectId, [to], PredicateID) select E.ID, E.Uid, S.ID, utility.GetHash(@salt + '|' + cast(S.ID as varchar)), T.ID, I.[Key], E.PredicateID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #ids I where MATCH(S-(E)->T) and E.PredicateUid = @predicateUid and E.ID not in (select ID from @preloadedIntersects) and T.ID = I.ID; end else begin insert into #hops (IntersectID, IntersectUid, SubjectID, [from], ObjectId, [to], PredicateID) select E.ID, E.Uid, S.ID, I.[Key], T.ID, utility.GetHash(@salt + '|' + cast(T.ID as varchar)), E.PredicateID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #ids I where MATCH(S-(E)->T) and E.PredicateUid = @predicateUid and E.ID not in (select ID from @preloadedIntersects) and S.ID = I.ID; end
drop table if exists #hopAssets create table #hopAssets (ID bigint, [Key] varchar(32)) insert into #hopAssets select H.SubjectID, H.[from] from #hops H left join #ids I on I.[Key] = H.[from] -- Do not other loading the incoming assets we want to reveal from. where I.[Key] is null group by H.SubjectID, H.[from]
insert into #hopAssets select H.ObjectID, H.[to] from #hops H left join #ids I on I.[Key] = H.[to] -- Do not other loading the incoming assets we want to reveal from. where I.[Key] is null group by H.ObjectID, H.[to];
drop table if exists #hierarchies create table #hierarchies ( Uid uniqueidentifier, ID bigint, ParentID bigint, AssetTypeID int, [Key] varchar(50), [ParentKey] varchar(50), UseAsTransformation bit default(0), IsSubjectInTransformation bit default(0), focal bit default(0), IsLeaf bit default(0), HasAssetReadAccess bit default(1) not null, HasResponsibilityReadAccess bit default(1) not null, Back varchar(25), BackAmount decimal(2,1), HierarchyKey varchar(50), HasTooManyChildren bit default(0) ); create clustered index cix_TempHierarchies on #hierarchies (HierarchyKey); create nonclustered index ix_TempHierarchies_ID on #hierarchies (ID); create nonclustered index ix_TempHierarchies_ParentID on #hierarchies (ParentID);
if @ancestry = 3 begin -- This is impact --Map assets of Diagram asset type and find process asset which they belong to drop table if exists #pdAssetsMap create table #pdAssetsMap( originalId int, processId int ) insert into #pdAssetsMap select distinct ha.id as origId, ta.id as processId from #hopAssets ha inner join asset a on a.id = ha.id inner join assettype at on at.id = a.assettypeid cross apply (select top 1 * from processexpandeddata pxd where pxd.fromuid = a.uid union select top 1 * from processexpandeddata pxd where pxd.touid = a.uid )PD inner join asset ta on ta.uid = PD.diagramassetuid where at.class = 15
if exists (select * from #pdAssetsMap) begin merge #hops h using #pdAssetsMap on h.[from] = utility.GetHash(@salt + '|' + cast(#pdAssetsMap.originalId as varchar)) when matched then update set h.[from] = utility.GetHash(@salt + '|' + cast(#pdAssetsMap.processId as varchar)); end
insert into #hierarchies (Uid, ID, AssetTypeID, [Key], ParentKey, focal) select isnull(P.uid,A.Uid), isnull(P.ID,A.ID), isnull(P.AssetTypeId,A.AssetTypeID), utility.GetHash(@salt + '|' + cast(isnull(P.ID,A.ID) as varchar)), utility.GetHash(@salt + '|' + cast(isnull(P.AssetTypeId,A.AssetTypeID) as varchar)), cast(0 as bit) as focal from Asset A inner join #hopAssets L on L.ID = A.ID left join #pdAssetsMap pdam on pdam.originalid = A.id left join asset p on p.id = pdam.processid; end else begin -- This is lineage with h as ( select A.Uid, A.ID, A.AssetTypeID, I.Object, I.ObjectID, P.ID ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID, cast(0 as bit) as focal from Asset A inner join #hopAssets L on L.ID = A.ID left join PredicateIntersect I on I.PredicateType in (3,4) and I.Object = A.Object and I.ObjectID = A.ObjectID left join Asset P on P.Object = I.Subject and P.ObjectID = I.SubjectID union all select A.Uid, A.ID, A.AssetTypeID, A.Object, A.ObjectID, I.ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID, h.focal from h inner join Asset A on h.ParentObject = A.Object and h.ParentObjectID = A.ObjectID outer apply ( select P.ID as ParentID, I.Subject, I.SubjectID from PredicateIntersect I inner join Asset P on P.Object = I.Subject and P.ObjectID = I.SubjectID where I.PredicateType in (3,4) and I.Object = A.Object and I.ObjectID = A.ObjectID ) I )
insert into #hierarchies (Uid, ID, ParentID, AssetTypeID, focal) select distinct Uid, ID, ParentID, AssetTypeID, focal from h
update H set H.[Key] = utility.GetHash(@salt + '|' + cast(H.ID as varchar)), H.[ParentKey] = case when H.ParentID is null then null else utility.GetHash(@salt + '|' + cast(H.ParentID as varchar)) end from #hierarchies H;
-- GOV-13214 and GOV-14396- Get children that may not be involved in lineage -------------------------------------- if @includeDescendantAssets = 1 begin declare @iterList TABLE(id int) insert into @iterList select id from #hopAssets
declare @iterID int
drop table if exists #additionalLineage create table #additionalLineage (Uid uniqueidentifier, ID bigint, ParentID bigint, AssetTypeID int, [Key] varchar(50), [ParentKey] varchar(50),focal int);
while(1 = 1) begin truncate table #additionalLineage
SET @iterID = NULL SELECT TOP(1) @iterID = id FROM @iterList
IF @iterID IS NULL BREAK
;with h as ( select L.[key] as Salt, C.Uid, C.ID, C.AssetTypeID, I.Object, I.ObjectID, A.ID ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID from Asset A inner join #hopAssets L on L.ID = A.ID inner join PredicateIntersect I on I.PredicateType in (3,4) and I.Subject = A.Object and I.SubjectID = A.ObjectID inner join Asset C on C.Object = I.Object and C.ObjectID = I.ObjectID where A.ID = @iterID union all select h.Salt, C.Uid, C.ID, C.AssetTypeID, C.Object, C.ObjectID, A.ID as ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID from h inner join Asset A on h.Object = A.Object and h.ObjectID = A.ObjectID inner join PredicateIntersect I on I.PredicateType in (3,4) and I.Subject = A.Object and I.SubjectID = A.ObjectID inner join Asset C on C.Object = I.Object and C.ObjectID = I.ObjectID ) insert into #additionalLineage ([Key], Uid, ID, ParentID, AssetTypeID, focal) select top(@maxLineageDescendants+1) utility.GetHash(h.salt + '|A' + cast(h.uid as varchar(36))), h.Uid, h.ID, h.ParentID, h.AssetTypeID, 0 from h
declare @cnt int = (select count(1) from #additionalLineage)
if (@cnt <= @maxLineageDescendants) begin insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey) select al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key] from #additionalLineage al cross apply (select top 1 [key] from #hierarchies where id = al.parentid)parent([key])
insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey) select al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key] from #additionalLineage al cross apply (select top 1 [key] from #additionalLineage where id = al.parentid)parent([key]) end
if (@cnt > @maxLineageDescendants) begin insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey,hastoomanychildren) select top 1 al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key], 1 from #additionalLineage al cross apply (select top 1 [key] from #hierarchies where id = al.parentid)parent([key])
insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey,hastoomanychildren) select top 1 al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key], 1 from #additionalLineage al cross apply (select top 1 [key] from #additionalLineage where id = al.parentid)parent([key]) end
DELETE TOP(1) FROM @iterList end
end ------------------------------------------------------------------------------------------------------ end
update H set HasAssetReadAccess = case when P.PermissionsBitMask & 1 = 1 then 1 else 0 end, HasResponsibilityReadAccess = case when P.PermissionsBitMask & 32 = 32 then 1 else 0 end from #hierarchies H cross apply dbo.UserAssetPermissions(@resourceId,H.AssetTypeID) P where P.AssetID = H.ID;
update H set HasAssetReadAccess = case when P.PermissionsBitMask & 1 = 1 then 1 else 0 end, HasResponsibilityReadAccess = case when P.PermissionsBitMask & 32 = 32 then 1 else 0 end from #hierarchies H cross apply dbo.UserAssetPermissions(@resourceId,H.AssetTypeID) P where P.AssetID = 0;
if @ancestry = 3 begin -- This is impact insert into #hierarchies (AssetTypeID, [Key], Uid, focal) select O.AssetTypeID, utility.GetHash(@salt + '|' + cast(O.AssetTypeID as varchar)), CAST(0x0 AS UNIQUEIDENTIFIER), O.focal from #hierarchies O left join #hierarchies C on C.ParentID = O.ID where C.ID is null and O.ParentID is null group by O.AssetTypeID, O.focal end else begin -- This is lineage insert into #hierarchies (AssetTypeID, [Key], Uid) select O.AssetTypeID, utility.GetHash(@salt + '|' + cast(O.AssetTypeID as varchar)), CAST(0x0 AS UNIQUEIDENTIFIER) from #hierarchies O left join #hierarchies C on C.ParentID = O.ID left join AssetType AT on AT.Id = O.AssetTypeId where C.ID is null and O.ParentID is null and AT.Class <> 15 group by O.AssetTypeID
-- Update parent key for single-level assets with key for asset type records added above. update O set O.ParentKey = utility.GetHash(@salt + '|' + cast(O.AssetTypeID as varchar)) from #hierarchies O left join #hierarchies C on C.ParentID = O.ID where C.ID is null and O.ParentID is null and O.ID is not null;
-- Handle Process Diagram Types if exists (select top 1 * from #hierarchies H left join AssetType AT on AT.Id = H.AssetTypeId where AT.Class = 15) begin drop table if exists #processDiagramMap create table #processDiagramMap ( huid uniqueidentifier, assetUid uniqueidentifier, assetTypeUid uniqueidentifier, assetTypeId int, parent_hash nvarchar(100))
insert into #processDiagramMap select distinct h.uid as huid, pxd.diagramassetuid as assetuid, pxd.diagramassettypeuid as assettypeuid, at.id as assettypeid, utility.GetHash(@salt + '|' + cast(pxd.diagramassetuid as nvarchar(36))) as parent_hash from #hierarchies h inner join processexpandeddata pxd on pxd.fromuid = h.uid inner join assettype at on at.uid = pxd.diagramassettypeuid union select distinct h.uid as huid, pxd.diagramassetuid as assetuid, pxd.diagramassettypeuid as assettypeuid, at.id as assettypeid, utility.GetHash(@salt + '|' + cast(pxd.diagramassetuid as nvarchar(36))) as parent_hash from #hierarchies h inner join processexpandeddata pxd on pxd.touid = h.uid inner join assettype at on at.uid = pxd.diagramassettypeuid
insert into #hierarchies (uid, AssetTypeID, [Key], ID) select pxd.assetuid as assetuid, pxd.assettypeid, pxd.parent_hash, a.id from #processDiagramMap pxd inner join #hierarchies h on h.uid = pxd.huid inner join asset a on a.uid = pxd.assetuid
update #hierarchies set parentkey = pxd.parent_hash from #processDiagramMap pxd where #hierarchies.uid = pxd.huid end end
-- Get count-related data for unique set of Asset IDs, then join to this #count table at the end. drop table if exists #counts; create table #counts (ID bigint, AssetTypeID int, ActionCount int, DisplayValue nvarchar(500)); create clustered index cix_TempCounts on #counts (ID)
insert into #counts (ID, AssetTypeID) select ID, AssetTypeID from #hierarchies where ID is not null group by ID, AssetTypeID;
update H set H.ActionCount = ( select count(1) as ActionCount from Issue I inner join Asset A on A.Object = I.Object and A.ObjectID = I.ObjectID where I.CompletedOn is null and exists (select 1 from workflow.Item where Object = 'Issue' and ObjectID = I.ID) and A.ID = H.ID group by A.Uid ), H.DisplayValue = DV.DisplayValue from #counts H left join AssetDisplayValue DV on DV.AssetID = H.ID;
update T set T.UseAsTransformation = S.UseAsTransformation, T.IsSubjectInTransformation = CASE WHEN ATO.Cnt = 0 THEN 0 ELSE 1 END from #hierarchies T inner join AssetType S on S.ID = T.AssetTypeID cross apply ( select count(*) from IntersectType IT left join AssetType ATO on ATO.Object = IT.Object and ATO.ObjectID = IT.ObjectID and ATO.UseAsTransformation = 1 where IT.Subject = S.Object and IT.SubjectID = S.ObjectID ) ATO(Cnt);
update T set T.IsLeaf = iif(C.ID is null, 1, 0) from #hierarchies T left join #hierarchies C on C.ParentKey = T.[Key];
-- Now calculate backAmount. with ba as ( select H.[Key], H.[ParentKey], S.IconBackColor as Back, cast(0 as decimal(2,1)) as BackAmount, H.[Key] as HierarchyKey from #hierarchies H inner join AssetTypeStyle S on S.ID = H.AssetTypeID where H.[ParentKey] is null union all select H.[Key], H.[ParentKey], P.Back, case when P.BackAmount = 0.8 then P.BackAmount else cast(P.BackAmount+0.2 as decimal(2,1)) end as BackAmount, P.HierarchyKey from #hierarchies H inner join ba P on P.[Key] = H.ParentKey )
update H set H.BackAmount = ba.BackAmount, H.Back = ba.Back, H.HierarchyKey = ba.HierarchyKey from #hierarchies H inner join ba on ba.[Key] = H.[Key];
--In case on Impact, map out how many process assets there are to return correct count drop table if exists #processAssetCountMap create table #processAssetCountMap( [key] varchar(50), [pUid] uniqueidentifier, [dir] int, [count] int )
if @ancestry = 3 begin ;with cte as (select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], E.PredicateUid as Uid, T.ID as AssetId, 1 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType in (16,17) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.ID = T.ID union all select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], E.PredicateUid as Uid, S.ID as AssetId, 2 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType in (16,17) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.ID = T.ID ) insert into #processAssetCountMap select t.[key], t.[uid], t.[direction], count(*) as count from ( select distinct cte.[key],cte.[uid], cte.direction, pxd.diagramassetuid from cte inner join asset a on a.id = cte.assetid inner join processexpandeddata pxd on pxd.fromuid = a.uid or pxd.touid = a.uid) t group by t.[key], t.[uid], t.[direction] end
-- Get flat node collection. drop table if exists #flatNodeCollection select distinct H.hierarchyKey, H.focal, H.IsLeaf as leaf, H.[key], H.parentKey as [group], H.Uid as assetUid, H.Id as assetId, H.assetTypeId, T.Uid as assetTypeUid, H.backAmount, H.back, coalesce(S.icon, 'fa-book') as icon, T.Class as class, coalesce(C.DisplayValue, T.Name) as [text], coalesce(C.ActionCount, 0) as actionCount, coalesce(H.useAsTransformation, 0) as useAsTransformation, H.hasAssetReadAccess, H.hasResponsibilityReadAccess, coalesce(H.isSubjectInTransformation, 0) as isSubjectInTransformation into #flatNodeCollection from #hierarchies H left join #counts C on C.ID = H.ID inner join AssetType T on T.ID = H.AssetTypeID inner join AssetTypeStyle S on S.ID = T.ID order by H.hierarchyKey
---handle nodes with too many children update S set S.leaf = 0, S.backAmount = 0, S.back = '#d73961', S.[text] = 'Assets with over '+ TRY_CAST(@maxLineageDescendants AS nvarchar(max)) + ' descendants can''t be shown in lineage', S.AssetUid = CONVERT(UNIQUEIDENTIFIER, 0x00), S.AssetTypeUid = CONVERT(UNIQUEIDENTIFIER, 0x00) from #flatNodeCollection S inner join #hierarchies h on S.hierarchykey = h.hierarchyKey and S.assetuid = h.uid and h.HasTooManyChildren = 1 ---end handling nodes with too many children
select * from #flatNodeCollection
select @hierarchyKey as [from], --iif(@direction = 'B', S.hierarchyKey, @hierarchyKey) as [from], iif(@direction = 'B', S.hierarchyKey, T.hierarchyKey) as [to], -- iif(@direction = 'B', @hierarchyKey, T.hierarchyKey) as [to], '#cccccc' as [back], H.predicateId, P.Uid as predicateUid, iif(@direction = 'B', P.Inverse, P.Name) as [text], P.[Type] as predicateType, ( select Hi.intersectId as id, Hi.[from], Hi.[to] from #hops Hi left join #hierarchies Si on Si.[key] = Hi.[from] and Si.hierarchyKey = S.hierarchyKey left join #hierarchies Ti on Ti.[key] = Hi.[to] and Ti.hierarchyKey = T.hierarchyKey for json path ) as linksJson from #hops H left join #hierarchies S on S.[key] = H.[from] left join #hierarchies T on T.[key] = H.[to] inner join [Predicate] P on P.ID = H.PredicateID group by S.hierarchyKey, T.hierarchyKey, H.predicateId, P.Uid, iif(@direction = 'B', P.Inverse, P.Name), P.Type;
select H.hierarchyKey, ( select H.hierarchyKey + '-O-' + cast(responsibilityTypeId as varchar) as [key], ResponsibilityTypeName as responsibilityType, responsibilityTypeId, count(1) as [count], cast(0 as bit) as expanded from ( select Ro.ResponsibilityTypeName, Ro.ResponsibilityTypeID, Ro.ResourceID from ResponsibilityDetail Ro inner join #hierarchies Ho on Ho.hierarchyKey = H.hierarchyKey and ( Ho.ID = Ro.AssetID or (Ro.AssetID = 0 and Ho.AssetTypeID = Ro.AssetTypeID) ) and Ro.IsVisible = 1 and ( (@includeNonLeaf = 0 and Ho.IsLeaf = 1) or (@includeNonLeaf = 1) ) group by Ro.ResponsibilityTypeName, Ro.ResponsibilityTypeID, Ro.ResourceID ) O group by ResponsibilityTypeName, ResponsibilityTypeID order by ResponsibilityTypeName for json path ) as ownersJson, ( select [predicate], ID as predicateId, Uid as predicateUid, direction, isnull(pacm.count,count(1)) as [count], cast(0 as bit) as expanded from ( select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], (select top 1 Name from Predicate where ID = E.PredicateID) as [Predicate], -- Improves performance 10x E.PredicateID as ID, E.PredicateUid as Uid, T.ID as AssetId, 1 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType not in (select ID from @offLimitImpactFunctionalTypes) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.hierarchyKey = H.hierarchyKey and Hr.ID = S.ID and ( (@includeNonLeaf = 0 and Hr.IsLeaf = 1) or (@includeNonLeaf = 1) ) union all select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], (select top 1 Inverse from Predicate where ID = E.PredicateID) as [Predicate], -- Improves performance 10x E.PredicateID as ID, E.PredicateUid as Uid, S.ID as AssetId, 2 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType not in (select ID from @offLimitImpactFunctionalTypes) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.hierarchyKey = H.hierarchyKey and Hr.ID = T.ID and ( (@includeNonLeaf = 0 and Hr.IsLeaf = 1) or (@includeNonLeaf = 1) ) ) O left join #processAssetCountMap pacm on pacm.puid = O.uid and pacm.dir = O.direction and pacm.[key] = O.[key] group by [Predicate], ID, Uid, Direction,O.[key],pacm.[count] for json path ) as relationsJson from #hierarchies H group by H.hierarchyKey end

changeSet.rollback:
CREATE OR ALTER procedure [graph].[AssetBrowser_ImpactHop] @ancestry int, -- 1 = all, 2 = direct-parent, 3 = type-only @hierarchyKey varchar(50), @assets dbo.AssetBrowserImpactTable readonly, @preloadedIntersects dbo.Ids readonly, @predicateUid uniqueidentifier, @direction char(1) = 'F', -- (F)orward, (B)ackward @resourceId int, @isAdmin bit, @includeNonLeaf bit = 1, @includeDescendantAssets bit = 1 as begin set nocount on;
declare @offLimitImpactFunctionalTypes table (ID int) declare @maxLineageDescendants int = 500
insert into @offLimitImpactFunctionalTypes (ID) values (15) if @ancestry = 1 begin insert into @offLimitImpactFunctionalTypes (ID) values (1),(3),(4) end
drop table if exists #ids; create table #ids ([Key] varchar(50), ID bigint);
drop table if exists #hops; create table #hops (IntersectID bigint, IntersectUid uniqueidentifier, SubjectID bigint, SubjectSalt varchar(25), [from] varchar(50), ObjectId bigint, ObjectSalt varchar(25), [to] varchar(50), PredicateID int); create nonclustered index IX_TempHops_IntersectID on #hops (IntersectID asc);
insert into #ids ([Key], ID) select O.[Key], A.ID from @assets O inner join Asset A on A.Uid = O.Uid;
--Predicates of type 16 means that we want to see contents of process diagram, so lets unpack it and add diagram assets manually if exists(select top 1 * from [Predicate] where uid = @predicateUid and [type] = 16) begin
drop table if exists #diagramIds; create table #diagramIds ([Key] varchar(50), ID bigint);
insert into #diagramIds select ass.[key], a.id from @assets ass inner join asset a on a.uid = ass.uid where a.object != 'Diagram'
;with asset_cte as( select da.id, h.[key] from #diagramIds h inner join assetprocessdiagram d on d.assetid = h.id inner join asset a on a.id = h.id inner join processexpandeddata pxd on pxd.diagramassetuid = a.uid inner join asset da on da.uid = pxd.fromuid inner join assettype at on at.id = da.assettypeid inner join intersecttype it on at.uid = it.subjectuid inner join [predicate] p on it.predicateid = p.id where h.id is not null and p.type = 16 union select da.id, h.[key] from #diagramIds h inner join assetprocessdiagram d on d.assetid = h.id inner join asset a on a.id = h.id inner join processexpandeddata pxd on pxd.diagramassetuid = a.uid inner join asset da on da.uid = pxd.touid inner join assettype at on at.id = da.assettypeid inner join intersecttype it on at.uid = it.subjectuid inner join [predicate] p on it.predicateid = p.id where h.id is not null and p.type = 16 ) insert into #ids select [key],id from asset_cte end
declare @salt varchar(25) = graph.Hop_GenerateSalt()
-- Relationships if @direction = 'B' begin insert into #hops (IntersectID, IntersectUid, SubjectID, [from], ObjectId, [to], PredicateID) select E.ID, E.Uid, S.ID, utility.GetHash(@salt + '|' + cast(S.ID as varchar)), T.ID, I.[Key], E.PredicateID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #ids I where MATCH(S-(E)->T) and E.PredicateUid = @predicateUid and E.ID not in (select ID from @preloadedIntersects) and T.ID = I.ID; end else begin insert into #hops (IntersectID, IntersectUid, SubjectID, [from], ObjectId, [to], PredicateID) select E.ID, E.Uid, S.ID, I.[Key], T.ID, utility.GetHash(@salt + '|' + cast(T.ID as varchar)), E.PredicateID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #ids I where MATCH(S-(E)->T) and E.PredicateUid = @predicateUid and E.ID not in (select ID from @preloadedIntersects) and S.ID = I.ID; end
drop table if exists #hopAssets create table #hopAssets (ID bigint, [Key] varchar(32)) insert into #hopAssets select H.SubjectID, H.[from] from #hops H left join #ids I on I.[Key] = H.[from] -- Do not other loading the incoming assets we want to reveal from. where I.[Key] is null group by H.SubjectID, H.[from]
insert into #hopAssets select H.ObjectID, H.[to] from #hops H left join #ids I on I.[Key] = H.[to] -- Do not other loading the incoming assets we want to reveal from. where I.[Key] is null group by H.ObjectID, H.[to];
drop table if exists #hierarchies create table #hierarchies ( Uid uniqueidentifier, ID bigint, ParentID bigint, AssetTypeID int, [Key] varchar(50), [ParentKey] varchar(50), UseAsTransformation bit default(0), IsSubjectInTransformation bit default(0), focal bit default(0), IsLeaf bit default(0), HasAssetReadAccess bit default(1) not null, Back varchar(25), BackAmount decimal(2,1), HierarchyKey varchar(50), HasTooManyChildren bit default(0) ); create clustered index cix_TempHierarchies on #hierarchies (HierarchyKey); create nonclustered index ix_TempHierarchies_ID on #hierarchies (ID); create nonclustered index ix_TempHierarchies_ParentID on #hierarchies (ParentID);
if @ancestry = 3 begin -- This is impact --Map assets of Diagram asset type and find process asset which they belong to drop table if exists #pdAssetsMap create table #pdAssetsMap( originalId int, processId int ) insert into #pdAssetsMap select distinct ha.id as origId, ta.id as processId from #hopAssets ha inner join asset a on a.id = ha.id inner join assettype at on at.id = a.assettypeid cross apply (select top 1 * from processexpandeddata pxd where pxd.fromuid = a.uid union select top 1 * from processexpandeddata pxd where pxd.touid = a.uid )PD inner join asset ta on ta.uid = PD.diagramassetuid where at.class = 15
if exists (select * from #pdAssetsMap) begin merge #hops h using #pdAssetsMap on h.[from] = utility.GetHash(@salt + '|' + cast(#pdAssetsMap.originalId as varchar)) when matched then update set h.[from] = utility.GetHash(@salt + '|' + cast(#pdAssetsMap.processId as varchar)); end
insert into #hierarchies (Uid, ID, AssetTypeID, [Key], ParentKey, focal) select isnull(P.uid,A.Uid), isnull(P.ID,A.ID), isnull(P.AssetTypeId,A.AssetTypeID), utility.GetHash(@salt + '|' + cast(isnull(P.ID,A.ID) as varchar)), utility.GetHash(@salt + '|' + cast(isnull(P.AssetTypeId,A.AssetTypeID) as varchar)), cast(0 as bit) as focal from Asset A inner join #hopAssets L on L.ID = A.ID left join #pdAssetsMap pdam on pdam.originalid = A.id left join asset p on p.id = pdam.processid; end else begin -- This is lineage with h as ( select A.Uid, A.ID, A.AssetTypeID, I.Object, I.ObjectID, P.ID ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID, cast(0 as bit) as focal from Asset A inner join #hopAssets L on L.ID = A.ID left join PredicateIntersect I on I.PredicateType in (3,4) and I.Object = A.Object and I.ObjectID = A.ObjectID left join Asset P on P.Object = I.Subject and P.ObjectID = I.SubjectID union all select A.Uid, A.ID, A.AssetTypeID, A.Object, A.ObjectID, I.ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID, h.focal from h inner join Asset A on h.ParentObject = A.Object and h.ParentObjectID = A.ObjectID outer apply ( select P.ID as ParentID, I.Subject, I.SubjectID from PredicateIntersect I inner join Asset P on P.Object = I.Subject and P.ObjectID = I.SubjectID where I.PredicateType in (3,4) and I.Object = A.Object and I.ObjectID = A.ObjectID ) I )
insert into #hierarchies (Uid, ID, ParentID, AssetTypeID, focal) select distinct Uid, ID, ParentID, AssetTypeID, focal from h
update H set H.[Key] = utility.GetHash(@salt + '|' + cast(H.ID as varchar)), H.[ParentKey] = case when H.ParentID is null then null else utility.GetHash(@salt + '|' + cast(H.ParentID as varchar)) end from #hierarchies H;
-- GOV-13214 and GOV-14396- Get children that may not be involved in lineage -------------------------------------- if @includeDescendantAssets = 1 begin declare @iterList TABLE(id int) insert into @iterList select id from #hopAssets
declare @iterID int
drop table if exists #additionalLineage create table #additionalLineage (Uid uniqueidentifier, ID bigint, ParentID bigint, AssetTypeID int, [Key] varchar(50), [ParentKey] varchar(50),focal int);
while(1 = 1) begin truncate table #additionalLineage
SET @iterID = NULL SELECT TOP(1) @iterID = id FROM @iterList
IF @iterID IS NULL BREAK
;with h as ( select L.[key] as Salt, C.Uid, C.ID, C.AssetTypeID, I.Object, I.ObjectID, A.ID ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID from Asset A inner join #hopAssets L on L.ID = A.ID inner join PredicateIntersect I on I.PredicateType in (3,4) and I.Subject = A.Object and I.SubjectID = A.ObjectID inner join Asset C on C.Object = I.Object and C.ObjectID = I.ObjectID where A.ID = @iterID union all select h.Salt, C.Uid, C.ID, C.AssetTypeID, C.Object, C.ObjectID, A.ID as ParentID, I.Subject as ParentObject, I.SubjectID as ParentObjectID from h inner join Asset A on h.Object = A.Object and h.ObjectID = A.ObjectID inner join PredicateIntersect I on I.PredicateType in (3,4) and I.Subject = A.Object and I.SubjectID = A.ObjectID inner join Asset C on C.Object = I.Object and C.ObjectID = I.ObjectID ) insert into #additionalLineage ([Key], Uid, ID, ParentID, AssetTypeID, focal) select top(@maxLineageDescendants+1) utility.GetHash(h.salt + '|A' + cast(h.uid as varchar(36))), h.Uid, h.ID, h.ParentID, h.AssetTypeID, 0 from h
declare @cnt int = (select count(1) from #additionalLineage)
if (@cnt <= @maxLineageDescendants) begin insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey) select al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key] from #additionalLineage al cross apply (select top 1 [key] from #hierarchies where id = al.parentid)parent([key])
insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey) select al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key] from #additionalLineage al cross apply (select top 1 [key] from #additionalLineage where id = al.parentid)parent([key]) end
if (@cnt > @maxLineageDescendants) begin insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey,hastoomanychildren) select top 1 al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key], 1 from #additionalLineage al cross apply (select top 1 [key] from #hierarchies where id = al.parentid)parent([key])
insert into #hierarchies (uid,id, parentid, assettypeid, [key],parentkey,hastoomanychildren) select top 1 al.uid,al.id,al.parentid, al.assettypeid,al.[key],parent.[key], 1 from #additionalLineage al cross apply (select top 1 [key] from #additionalLineage where id = al.parentid)parent([key]) end
DELETE TOP(1) FROM @iterList end
end ------------------------------------------------------------------------------------------------------ end
update H set HasAssetReadAccess = 0 from #hierarchies H cross apply dbo.UserAssetPermissions(@resourceId,H.AssetTypeID) P where P.AssetID = H.ID and P.PermissionsBitMask & 1 = 0;
update H set HasAssetReadAccess = 0 from #hierarchies H cross apply dbo.UserAssetPermissions(@resourceId,H.AssetTypeID) P where P.AssetID = 0 and P.PermissionsBitMask & 1 = 0;
if @ancestry = 3 begin -- This is impact insert into #hierarchies (AssetTypeID, [Key], Uid, focal) select O.AssetTypeID, utility.GetHash(@salt + '|' + cast(O.AssetTypeID as varchar)), CAST(0x0 AS UNIQUEIDENTIFIER), O.focal from #hierarchies O left join #hierarchies C on C.ParentID = O.ID where C.ID is null and O.ParentID is null group by O.AssetTypeID, O.focal end else begin -- This is lineage insert into #hierarchies (AssetTypeID, [Key], Uid) select O.AssetTypeID, utility.GetHash(@salt + '|' + cast(O.AssetTypeID as varchar)), CAST(0x0 AS UNIQUEIDENTIFIER) from #hierarchies O left join #hierarchies C on C.ParentID = O.ID left join AssetType AT on AT.Id = O.AssetTypeId where C.ID is null and O.ParentID is null and AT.Class <> 15 group by O.AssetTypeID
-- Update parent key for single-level assets with key for asset type records added above. update O set O.ParentKey = utility.GetHash(@salt + '|' + cast(O.AssetTypeID as varchar)) from #hierarchies O left join #hierarchies C on C.ParentID = O.ID where C.ID is null and O.ParentID is null and O.ID is not null;
-- Handle Process Diagram Types if exists (select top 1 * from #hierarchies H left join AssetType AT on AT.Id = H.AssetTypeId where AT.Class = 15) begin drop table if exists #processDiagramMap create table #processDiagramMap ( huid uniqueidentifier, assetUid uniqueidentifier, assetTypeUid uniqueidentifier, assetTypeId int, parent_hash nvarchar(100))
insert into #processDiagramMap select distinct h.uid as huid, pxd.diagramassetuid as assetuid, pxd.diagramassettypeuid as assettypeuid, at.id as assettypeid, utility.GetHash(@salt + '|' + cast(pxd.diagramassetuid as nvarchar(36))) as parent_hash from #hierarchies h inner join processexpandeddata pxd on pxd.fromuid = h.uid inner join assettype at on at.uid = pxd.diagramassettypeuid union select distinct h.uid as huid, pxd.diagramassetuid as assetuid, pxd.diagramassettypeuid as assettypeuid, at.id as assettypeid, utility.GetHash(@salt + '|' + cast(pxd.diagramassetuid as nvarchar(36))) as parent_hash from #hierarchies h inner join processexpandeddata pxd on pxd.touid = h.uid inner join assettype at on at.uid = pxd.diagramassettypeuid
insert into #hierarchies (uid, AssetTypeID, [Key], ID) select pxd.assetuid as assetuid, pxd.assettypeid, pxd.parent_hash, a.id from #processDiagramMap pxd inner join #hierarchies h on h.uid = pxd.huid inner join asset a on a.uid = pxd.assetuid
update #hierarchies set parentkey = pxd.parent_hash from #processDiagramMap pxd where #hierarchies.uid = pxd.huid end end
-- Get count-related data for unique set of Asset IDs, then join to this #count table at the end. drop table if exists #counts; create table #counts (ID bigint, AssetTypeID int, ActionCount int, DisplayValue nvarchar(500)); create clustered index cix_TempCounts on #counts (ID)
insert into #counts (ID, AssetTypeID) select ID, AssetTypeID from #hierarchies where ID is not null group by ID, AssetTypeID;
update H set H.ActionCount = ( select count(1) as ActionCount from Issue I inner join Asset A on A.Object = I.Object and A.ObjectID = I.ObjectID where I.CompletedOn is null and exists (select 1 from workflow.Item where Object = 'Issue' and ObjectID = I.ID) and A.ID = H.ID group by A.Uid ), H.DisplayValue = DV.DisplayValue from #counts H left join AssetDisplayValue DV on DV.AssetID = H.ID;
update T set T.UseAsTransformation = S.UseAsTransformation, T.IsSubjectInTransformation = CASE WHEN ATO.Cnt = 0 THEN 0 ELSE 1 END from #hierarchies T inner join AssetType S on S.ID = T.AssetTypeID cross apply ( select count(*) from IntersectType IT left join AssetType ATO on ATO.Object = IT.Object and ATO.ObjectID = IT.ObjectID and ATO.UseAsTransformation = 1 where IT.Subject = S.Object and IT.SubjectID = S.ObjectID ) ATO(Cnt);
update T set T.IsLeaf = iif(C.ID is null, 1, 0) from #hierarchies T left join #hierarchies C on C.ParentKey = T.[Key];
-- Now calculate backAmount. with ba as ( select H.[Key], H.[ParentKey], S.IconBackColor as Back, cast(0 as decimal(2,1)) as BackAmount, H.[Key] as HierarchyKey from #hierarchies H inner join AssetTypeStyle S on S.ID = H.AssetTypeID where H.[ParentKey] is null union all select H.[Key], H.[ParentKey], P.Back, case when P.BackAmount = 0.8 then P.BackAmount else cast(P.BackAmount+0.2 as decimal(2,1)) end as BackAmount, P.HierarchyKey from #hierarchies H inner join ba P on P.[Key] = H.ParentKey )
update H set H.BackAmount = ba.BackAmount, H.Back = ba.Back, H.HierarchyKey = ba.HierarchyKey from #hierarchies H inner join ba on ba.[Key] = H.[Key];
--In case on Impact, map out how many process assets there are to return correct count drop table if exists #processAssetCountMap create table #processAssetCountMap( [key] varchar(50), [pUid] uniqueidentifier, [dir] int, [count] int )
if @ancestry = 3 begin ;with cte as (select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], E.PredicateUid as Uid, T.ID as AssetId, 1 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType in (16,17) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.ID = T.ID union all select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], E.PredicateUid as Uid, S.ID as AssetId, 2 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType in (16,17) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.ID = T.ID ) insert into #processAssetCountMap select t.[key], t.[uid], t.[direction], count(*) as count from ( select distinct cte.[key],cte.[uid], cte.direction, pxd.diagramassetuid from cte inner join asset a on a.id = cte.assetid inner join processexpandeddata pxd on pxd.fromuid = a.uid or pxd.touid = a.uid) t group by t.[key], t.[uid], t.[direction] end
-- Get flat node collection. drop table if exists #flatNodeCollection select distinct H.hierarchyKey, H.focal, H.IsLeaf as leaf, H.[key], H.parentKey as [group], H.Uid as assetUid, H.assetTypeId, T.Uid as assetTypeUid, H.backAmount, H.back, coalesce(S.icon, 'fa-book') as icon, T.Class as class, coalesce(C.DisplayValue, T.Name) as [text], coalesce(C.ActionCount, 0) as actionCount, coalesce(H.useAsTransformation, 0) as useAsTransformation, H.hasAssetReadAccess, coalesce(H.isSubjectInTransformation, 0) as isSubjectInTransformation into #flatNodeCollection from #hierarchies H left join #counts C on C.ID = H.ID inner join AssetType T on T.ID = H.AssetTypeID inner join AssetTypeStyle S on S.ID = T.ID order by H.hierarchyKey
---handle nodes with too many children update S set S.leaf = 0, S.backAmount = 0, S.back = '#d73961', S.[text] = 'Assets with over '+ TRY_CAST(@maxLineageDescendants AS nvarchar(max)) + ' descendants can''t be shown in lineage', S.AssetUid = CONVERT(UNIQUEIDENTIFIER, 0x00), S.AssetTypeUid = CONVERT(UNIQUEIDENTIFIER, 0x00) from #flatNodeCollection S inner join #hierarchies h on S.hierarchykey = h.hierarchyKey and S.assetuid = h.uid and h.HasTooManyChildren = 1 ---end handling nodes with too many children
select * from #flatNodeCollection
select @hierarchyKey as [from], --iif(@direction = 'B', S.hierarchyKey, @hierarchyKey) as [from], iif(@direction = 'B', S.hierarchyKey, T.hierarchyKey) as [to], -- iif(@direction = 'B', @hierarchyKey, T.hierarchyKey) as [to], '#cccccc' as [back], H.predicateId, P.Uid as predicateUid, iif(@direction = 'B', P.Inverse, P.Name) as [text], P.[Type] as predicateType, ( select Hi.intersectId as id, Hi.[from], Hi.[to] from #hops Hi left join #hierarchies Si on Si.[key] = Hi.[from] and Si.hierarchyKey = S.hierarchyKey left join #hierarchies Ti on Ti.[key] = Hi.[to] and Ti.hierarchyKey = T.hierarchyKey for json path ) as linksJson from #hops H left join #hierarchies S on S.[key] = H.[from] left join #hierarchies T on T.[key] = H.[to] inner join [Predicate] P on P.ID = H.PredicateID group by S.hierarchyKey, T.hierarchyKey, H.predicateId, P.Uid, iif(@direction = 'B', P.Inverse, P.Name), P.Type;
select H.hierarchyKey, ( select H.hierarchyKey + '-O-' + cast(responsibilityTypeId as varchar) as [key], ResponsibilityTypeName as responsibilityType, responsibilityTypeId, count(1) as [count], cast(0 as bit) as expanded from ( select Ro.ResponsibilityTypeName, Ro.ResponsibilityTypeID, Ro.ResourceID from ResponsibilityDetail Ro inner join #hierarchies Ho on Ho.hierarchyKey = H.hierarchyKey and ( Ho.ID = Ro.AssetID or (Ro.AssetID = 0 and Ho.AssetTypeID = Ro.AssetTypeID) ) and Ro.IsVisible = 1 and ( (@includeNonLeaf = 0 and Ho.IsLeaf = 1) or (@includeNonLeaf = 1) ) group by Ro.ResponsibilityTypeName, Ro.ResponsibilityTypeID, Ro.ResourceID ) O group by ResponsibilityTypeName, ResponsibilityTypeID order by ResponsibilityTypeName for json path ) as ownersJson, ( select [predicate], ID as predicateId, Uid as predicateUid, direction, isnull(pacm.count,count(1)) as [count], cast(0 as bit) as expanded from ( select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], (select top 1 Name from Predicate where ID = E.PredicateID) as [Predicate], -- Improves performance 10x E.PredicateID as ID, E.PredicateUid as Uid, T.ID as AssetId, 1 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType not in (select ID from @offLimitImpactFunctionalTypes) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.hierarchyKey = H.hierarchyKey and Hr.ID = S.ID and ( (@includeNonLeaf = 0 and Hr.IsLeaf = 1) or (@includeNonLeaf = 1) ) union all select distinct Hr.hierarchyKey + '-R-' + cast(E.PredicateID as varchar) as [key], (select top 1 Inverse from Predicate where ID = E.PredicateID) as [Predicate], -- Improves performance 10x E.PredicateID as ID, E.PredicateUid as Uid, S.ID as AssetId, 2 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #hierarchies Hr where MATCH(S-(E)->T) and E.PredicateType not in (select ID from @offLimitImpactFunctionalTypes) and E.ID not in (select ID from @preloadedIntersects) and E.ID not in (select IntersectID from #hops) and Hr.hierarchyKey = H.hierarchyKey and Hr.ID = T.ID and ( (@includeNonLeaf = 0 and Hr.IsLeaf = 1) or (@includeNonLeaf = 1) ) ) O left join #processAssetCountMap pacm on pacm.puid = O.uid and pacm.dir = O.direction and pacm.[key] = O.[key] group by [Predicate], ID, Uid, Direction,O.[key],pacm.[count] for json path ) as relationsJson from #hierarchies H group by H.hierarchyKey end
